import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, TotalUsageMetadata} from '../types/ai.js';

// specs/hal-engine-config-hooks/spec.md#12
it('exposes turn total usage to the response hook', async () => {
  const provider: AIProvider = {
    async *sendMessage() {
      yield {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 2, outputTokens: 3, totalTokens: 5}};
    },
    async generateStructured<T>() {
      return {} as T;
    },
  };
  let total: TotalUsageMetadata | undefined;
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), undefined, {
    hooks: {afterModelResponse: async (_session, _text, usage) => { total = usage; }},
  });
  await orchestrator.processMessage({
    sessionId: '1', userId: '1', entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}],
  });
  expect(total).toEqual({inputTokens: 2, outputTokens: 3, totalTokens: 5});
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/totalUsageContract.test.ts"
